sys_variable_value.value:
(function execute(inputs, outputs) {

var BodyJson = {
  "fields": {
     "description": {
      "content": [
        {
          "content": [
            {
              "text": inputs.desc,
              "type": "text"
            }
          ],
          "type": "paragraph"
        }
      ],
      "type": "doc",
      "version": 1
    },
    "issuetype": {
      "id": "10002"
    },
    "project": {
      "key": "DEMO"
    },
    "summary": inputs.short,
  },
  "update": {}
}
outputs.body_json = BodyJson;

})(inputs, outputs);

